#!/usr/bin/env python3
"""Persona 3 theme greeting: a tarot-style card as pixel art (CARD below: a placeholder
moon-over-water card; tools/make-pixel.py embeds your own card image instead). It flips in from its back, then a holographic sheen
sweeps across it now and then, next to fastfetch output, until the shell
stops it (see the fish greeting hook). Half-block pixels: W x 2H.
`python3 persona.py --still` prints one frame (for previewing)."""
import functools, json, math, os, random, re, subprocess, sys, time

W, H = 26, 14
PW, PH = W * 2, H * 3          # sextant cells: 2 x 3 sub-pixels each
FPS = 15

DEEP = (3, 10, 38)
NAVY = (8, 24, 84)
BLUE = (18, 56, 214)
AZURE = (47, 123, 255)
CYAN = (63, 216, 255)
ICE = (170, 242, 255)
WHITE = (242, 251, 255)
GOLD = (255, 214, 64)
GOLD_D = (190, 140, 30)

# card rectangle (pixels)
CX0, CX1 = 4, 4 + 44 - 1   # inclusive sub-pixel columns (= CW from tools/make-pixel.py)
CY0, CY1 = 0, 42 - 1       # inclusive sub-pixel rows (= CH)
CMID = (CX0 + CX1) / 2

# CARD-DATA start (generated by tools/make-pixel.py — do not edit)
CW, CH = 44, 42
CARD = bytes.fromhex("")
# CARD-DATA end

def mix(a, b, t):
    t = 0.0 if t < 0 else 1.0 if t > 1 else t
    return (a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t)

def info():
    cfg = os.path.expanduser("~/.config/fastfetch/persona.jsonc")
    out = subprocess.run(["fastfetch", "--logo", "none", "--pipe", "false", "-c", cfg],
                         capture_output=True, text=True).stdout
    return out.rstrip("\n").split("\n")

# ── tiny pixel font (3x5) for the card labels ───────────────────────────────────
FONT = {
    "0": ["111", "101", "101", "101", "111"],
    "F": ["111", "100", "110", "100", "100"],
    "O": ["111", "101", "101", "101", "111"],
    "L": ["100", "100", "100", "100", "111"],
}

def text_pixels(s, x0, y0):
    pts = []
    for i, ch in enumerate(s):
        for r, row in enumerate(FONT[ch]):
            for c, bit in enumerate(row):
                if bit == "1":
                    pts.append((x0 + i * 4 + c, y0 + r))
    return pts

LABEL_TOP = text_pixels("0", int(CMID) - 1, 4)
LABEL_BOT = text_pixels("FOOL", int(CMID) - 7, CY1 - 10)

# ── emblem geometry ─────────────────────────────────────────────────────────────
MX, MY, MR = CMID + 0.5, 15.5, 6.0      # moon
WATER_Y = 24                            # waterline

def in_card(x, y):
    return CX0 <= x <= CX1 and CY0 <= y <= CY1

def frame_kind(x, y):
    """0 inside panel, 1 outer white edge, 2 cyan band, 3 inner white hairline, None outside."""
    if not in_card(x, y):
        return None
    d = min(x - CX0, CX1 - x, y - CY0, CY1 - y)
    if d == 0:
        return 1
    if d in (1, 2):
        return 2
    if d == 3:
        return 3
    return 0

@functools.cache
def _static():
    """Card front without the moving parts, worked out once."""
    px = {}
    for y in range(PH):
        for x in range(PW):
            k = frame_kind(x, y)
            if k is None:
                continue
            if k == 1:
                px[(x, y)] = WHITE
            elif k == 2:
                px[(x, y)] = CYAN if (x + y) % 4 else ICE
            elif k == 3:
                px[(x, y)] = WHITE
            else:
                # sky: navy at the top to blue at the waterline; sea below
                if y < WATER_Y:
                    px[(x, y)] = mix(DEEP, BLUE, (y - CY0) / (WATER_Y - CY0) * 0.9)
                else:
                    px[(x, y)] = mix(BLUE, NAVY, (y - WATER_Y) / (CY1 - WATER_Y))
    # corner ornaments: little diamonds just inside the band
    for cx, cy in ((CX0 + 5, CY0 + 5), (CX1 - 5, CY0 + 5), (CX0 + 5, CY1 - 5), (CX1 - 5, CY1 - 5)):
        for dx, dy in ((0, 0), (1, 0), (-1, 0), (0, 1), (0, -1)):
            px[(cx + dx, cy + dy)] = GOLD if (dx, dy) == (0, 0) else ICE
    # label plates behind the "0" and "FOOL"
    for y in range(3, 10):
        for x in range(int(CMID) - 4, int(CMID) + 6):
            px[(x, y)] = NAVY
    for y in range(CY1 - 11, CY1 - 4):
        for x in range(int(CMID) - 9, int(CMID) + 10):
            if in_card(x, y) and frame_kind(x, y) == 0:
                px[(x, y)] = NAVY
    for x, y in LABEL_TOP + LABEL_BOT:
        px[(x, y)] = WHITE
    # fixed stars
    rnd = random.Random(7)
    stars = []
    for _ in range(14):
        sx, sy = rnd.randint(CX0 + 5, CX1 - 5), rnd.randint(10, WATER_Y - 2)
        if math.hypot(sx - MX, sy - MY) > MR + 2:
            stars.append((sx, sy, rnd.random() * 6.28))
    return px, stars

@functools.cache
def _back():
    """Card back: navy with a cyan diamond lattice and a white frame."""
    px = {}
    for y in range(PH):
        for x in range(PW):
            k = frame_kind(x, y)
            if k is None:
                continue
            if k in (1, 3):
                px[(x, y)] = WHITE
            elif k == 2:
                px[(x, y)] = CYAN
            else:
                lat = ((x - CX0) + (y - CY0)) % 6 == 0 or ((x - CX0) - (y - CY0)) % 6 == 0
                px[(x, y)] = AZURE if lat else NAVY
    return px

@functools.cache
def _art():
    px = {}
    for y in range(CH):
        for x in range(CW):
            k = (y * CW + x) * 3
            px[(CX0 + x, CY0 + y)] = (CARD[k], CARD[k + 1], CARD[k + 2])
    return px

def front(t):
    px = dict(_art())
    # holographic sheen: a soft diagonal band crosses the card every 4.5 s, tinting the light
    # checker pattern (dark silhouette untouched) with a cyan-pink shimmer
    period, cross = 4.5, 1.4
    p = (t % period) / cross
    if p < 1:
        span = (CX1 - CX0) + (CY1 - CY0) * 0.5
        pos = -6 + p * (span + 12)
        for (x, y), c in px.items():
            d = (x - CX0) + (y - CY0) * 0.5 - pos
            if abs(d) < 5:
                lum = (c[0] + c[1] + c[2]) / 3
                if lum > 70:
                    k = (1 - abs(d) / 5) * 0.55
                    tint = mix(ICE, (255, 170, 230), (y - CY0) / (CY1 - CY0))
                    px[(x, y)] = mix(c, tint, k)
    return px

def canvas(t=0.0):
    out = [[None] * PW for _ in range(PH)]
    # flip-in: the card turns from its back to the front over the first ~0.9s
    flip = 0.9
    if t < flip:
        ang = math.pi * (1 - t / flip)                # pi → 0
        sx = abs(math.cos(ang))
        face = _back() if ang > math.pi / 2 else front(t)
    else:
        sx, face = 1.0, front(t)
    half = (CX1 - CX0 + 1) / 2
    for y in range(CY0, CY1 + 1):
        for x in range(CX0, CX1 + 1):
            # sample the face, squeezed horizontally around the card's middle
            if sx < 0.04:
                continue
            u = (x + 0.5 - CMID) / sx + CMID
            if CX0 <= u <= CX1 + 0.99:
                c = face.get((int(u), y))
                if c:
                    out[y][x] = c
    return out

def _c(c): return _ci(int(c[0]), int(c[1]), int(c[2]))

@functools.lru_cache(maxsize=8192)
def _ci(r, g, b): return f"{r};{g};{b}"

def _sextant(bits):
    """Character for a 2x3 cell; bit k set = sub-pixel k (row-major from top-left) in fg."""
    if bits == 0: return " "
    if bits == 63: return "\u2588"
    if bits == 21: return "\u258c"
    if bits == 42: return "\u2590"
    return chr(0x1FB00 + bits - 1 - (bits > 21) - (bits > 42))

def _lum(c): return c[0] * 0.3 + c[1] * 0.59 + c[2] * 0.11

def render(px):
    """Sextant renderer: each cell's 6 sub-pixels split into a dark and a light group (two
    colours per cell, the group averages); empty sub-pixels show the terminal background."""
    rows = []
    for r in range(H):
        out, cur = [], None
        for c in range(W):
            cells = [px[3 * r + k // 2][2 * c + k % 2] for k in range(6)]
            filled = [p for p in cells if p]
            if not filled:
                seq = "\x1b[0m"; ch = " "
            elif len(filled) < 6:
                # card edge (or a flip mid-turn): painted sub-pixels in one colour on the background
                avg = tuple(sum(p[i] for p in filled) / len(filled) for i in range(3))
                bits = sum(1 << k for k, p in enumerate(cells) if p)
                seq, ch = f"\x1b[0;38;2;{_c(avg)}m", _sextant(bits)
            else:
                ls = [_lum(p) for p in cells]
                lo, hi = min(ls), max(ls)
                if hi - lo < 12:
                    avg = tuple(sum(p[i] for p in cells) / 6 for i in range(3))
                    seq, ch = f"\x1b[0;38;2;{_c(avg)}m", "\u2588"
                else:
                    mid = (lo + hi) / 2
                    bright = [p for p, l in zip(cells, ls) if l >= mid]
                    dim = [p for p, l in zip(cells, ls) if l < mid]
                    fg = tuple(sum(p[i] for p in bright) / len(bright) for i in range(3))
                    bg = tuple(sum(p[i] for p in dim) / len(dim) for i in range(3))
                    bits = sum(1 << k for k, l in enumerate(ls) if l >= mid)
                    seq, ch = f"\x1b[0;38;2;{_c(fg)};48;2;{_c(bg)}m", _sextant(bits)
            if seq != cur:
                out.append(seq); cur = seq
            out.append(ch)
        rows.append("".join(out) + "\x1b[0m")
    return rows

def cursor_row():
    """Ask the terminal where the cursor is (1-based row), or None."""
    import select, termios, tty
    fd = sys.stdin.fileno()
    old = termios.tcgetattr(fd)
    try:
        tty.setcbreak(fd)
        sys.stdout.write("\x1b[6n"); sys.stdout.flush()
        buf = ""
        while not buf.endswith("R"):
            if not select.select([fd], [], [], 0.3)[0]:
                return None
            buf += os.read(fd, 32).decode(errors="ignore")
        m = re.search(r"\x1b\[(\d+);(\d+)R", buf)
        return int(m.group(1)) if m else None
    finally:
        termios.tcsetattr(fd, termios.TCSADRAIN, old)

# ── kitty: the real card, full quality, via the graphics protocol ───────────────
FRAMES = os.path.expanduser("~/.local/share/persona-rice/media/p3/greeting-frames")

def motion_allowed():
    """The shared p3 Motion rule (~/.local/state/p3-motion.json): auto stops at/below the
    battery threshold when unplugged, always never stops, still never moves."""
    try:
        o = json.load(open(os.path.expanduser("~/.local/state/p3-motion.json")))
    except (OSError, ValueError):
        o = {}
    mode, thr = o.get("mode", "auto"), int(o.get("threshold", 30))
    if mode != "auto":
        return mode == "always"
    try:
        b = "/sys/class/power_supply/BAT0"
        return not (open(b + "/status").read().strip() == "Discharging" and int(open(b + "/capacity").read()) <= thr)
    except (OSError, ValueError):
        return True

def kitty_ok():
    # the full-resolution image mode is kept but off: the user wants the pixel-art card
    return os.environ.get("P3_GREET_IMAGE") == "1" and os.path.exists(os.path.join(FRAMES, "rest.png"))

def kitty_main(text, pidfile):
    import base64, fcntl, struct, termios, signal
    names = sorted(f for f in os.listdir(FRAMES) if f.startswith("flip-")) + ["rest.png"] + \
            sorted(f for f in os.listdir(FRAMES) if f.startswith("sheen-"))
    ids = {n: 61000 + i for i, n in enumerate(names)}
    rows_n, cols_n, xpx, ypx = struct.unpack("HHHH", fcntl.ioctl(sys.stdout.fileno(), termios.TIOCGWINSZ, b"\0" * 8))
    cw, ch = (xpx / cols_n or 9), (ypx / rows_n or 20)
    from_w, from_h = 304, 540
    R = max(16, len(text) + 2)
    C = max(4, round(R * ch * from_w / from_h / cw))
    Wk = C + 4
    rows = max(R, len(text))
    if cols_n < Wk + 40:
        print("\n".join(text)); return
    itop = max(0, (rows - len(text)) // 2)
    out = []
    for r in range(rows):
        ti = r - itop
        out.append(" " * Wk + (text[ti] if 0 <= ti < len(text) else "") + "\x1b[K")
    sys.stdout.write("\n".join(out) + "\n"); sys.stdout.flush()
    row = cursor_row()
    if row is None:
        return
    first = row - rows
    if first < 1:                       # printed rows scrolled past the top: place at row 1
        first = 1
    w = sys.stdout.buffer.write

    def g(ctrl, payload=b""):
        return b"\x1b_G" + ctrl.encode() + (b";" + payload if payload else b"") + b"\x1b\\"

    # load every frame from disk (kitty reads the files itself), invisible until placed
    buf = b""
    for n in names:
        buf += g(f"a=t,t=f,f=100,i={ids[n]},q=2", base64.b64encode(os.path.join(FRAMES, n).encode()))
    w(buf); sys.stdout.flush()
    shown = [None]

    def place(n, out_fd=None):
        b = b"\x1b7" + f"\x1b[{first + (rows - R) // 2};3H".encode() + \
            g(f"a=p,i={ids[n]},p=1,c={C},r={R},C=1,q=2") + b"\x1b8"
        if shown[0] is not None and shown[0] != n:
            b += g(f"a=d,d=i,i={ids[shown[0]]},q=2")
        shown[0] = n
        if out_fd is None:
            w(b); sys.stdout.flush()
        else:
            os.write(out_fd, b)

    flips = [n for n in names if n.startswith("flip-")]
    sheens = [n for n in names if n.startswith("sheen-")]
    if not motion_allowed() or not pidfile:
        place("rest.png"); return
    place(flips[0])
    if os.fork():                        # parent returns => prompt shows right away
        return
    fd = os.open("/dev/tty", os.O_WRONLY)
    def stop(*_):
        try: place("rest.png", fd)       # leave the clean card behind, never a mid-sheen frame
        finally: os._exit(0)
    for sig in (signal.SIGTERM, signal.SIGHUP, signal.SIGINT):
        signal.signal(sig, stop)
    with open(pidfile, "w") as f:
        f.write(str(os.getpid()))
    size = os.get_terminal_size(fd)
    seq = flips[1:] + ["rest.png"]
    t0 = time.monotonic(); k = 0
    try:
        while True:
            if os.get_terminal_size(fd) != size:
                return
            if not seq:
                seq = ["rest.png"] * int(3.1 * FPS) + sheens + ["rest.png"]
            n = seq.pop(0)
            if n != shown[0]:
                place(n, fd)
            k += 1
            time.sleep(max(0.0, k / FPS - (time.monotonic() - t0)))
    finally:
        try: os.remove(pidfile)
        except OSError: pass

def main():
    if "--still" in sys.argv:
        print("\n".join(render(canvas(float(os.environ.get("T", "2.0")))))); return
    pidfile = sys.argv[1] if len(sys.argv) > 1 else None   # where the shell looks for us
    text = info()
    if kitty_ok() and sys.stdin.isatty() and sys.stdout.isatty():
        return kitty_main(text, pidfile)
    rows = max(H, len(text))
    ok = sys.stdin.isatty() and sys.stdout.isatty()
    size = os.get_terminal_size() if ok else None
    top = max(0, (rows - H) // 2)
    itop = max(0, (rows - len(text)) // 2)

    def layout(d):
        out = []
        for r in range(rows):
            left = d[r - top] if 0 <= r - top < H else " " * W
            ti = r - itop
            right = text[ti] if 0 <= ti < len(text) else ""
            out.append(f"{left}  {right}\x1b[K")
        return out

    first_frame = render(canvas(0))
    # can't animate in place (animations paused, or the window is too short to keep the
    # greeting on screen): print the finished card instead of the first (back) frame
    if ok and size.columns >= W + 4 + 40 and (not motion_allowed() or size.lines < rows + 2):
        print("\n".join(layout(render(canvas(2.0))))); return
    if not ok or size.columns < W + 4 + 40:
        print("\n".join(layout(render(canvas(2.0))) if ok else text)); return
    sys.stdout.write("\n".join(layout(first_frame)) + "\n"); sys.stdout.flush()
    row = cursor_row()
    if not pidfile or row is None or row - rows < 1:
        return
    first = row - rows                       # 1-based row of the first printed line
    if os.fork():                            # parent returns => prompt shows right away
        return
    import signal
    for sig in (signal.SIGTERM, signal.SIGHUP, signal.SIGINT):
        signal.signal(sig, lambda *_: sys.exit(0))
    with open(pidfile, "w") as f:
        f.write(str(os.getpid()))
    fd = os.open("/dev/tty", os.O_WRONLY)
    t0 = time.monotonic()
    try:
        k = 0
        while True:
            if os.get_terminal_size(fd) != size:
                return
            t = time.monotonic() - t0
            d = render(canvas(t))
            buf = "\x1b7"
            for i, line in enumerate(d):
                buf += f"\x1b[{first + top + i};1H{line}"
            buf += "\x1b8"
            os.write(fd, buf.encode())
            k += 1
            time.sleep(max(0.0, k / FPS - (time.monotonic() - t0)))
    finally:
        try: os.remove(pidfile)
        except OSError: pass

if __name__ == "__main__":
    main()
